package org.strongswan.android.rookstride;
import android.content.*;import android.view.*;import android.widget.*;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.ext.junit.runners.AndroidJUnit4;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import org.strongswan.android.ui.RookstrideActivity;import java.util.*;import java.lang.reflect.*;
import static org.junit.Assert.*;import static org.hamcrest.Matchers.*;import static androidx.test.espresso.Espresso.*;import static androidx.test.espresso.action.ViewActions.*;import static androidx.test.espresso.matcher.ViewMatchers.*;import static androidx.test.espresso.assertion.ViewAssertions.*;
/** Signed native navigation, layout and action ownership. No server mutation in these UI fixtures. */
@RunWith(AndroidJUnit4.class) public class CompactNavigationUiTest {
 Context c;Vault vault;ArrayList<Gateway> old;Gateway a,b;String progress;Map<String,?> prefs;
 Object value(Object a,String key)throws Exception{Field f=a.getClass().getDeclaredField(key);f.setAccessible(true);return f.get(a);}
 void set(Object a,String key,Object v)throws Exception{Field f=a.getClass().getDeclaredField(key);f.setAccessible(true);f.set(a,v);}
 void call(Object a,String key,Class<?>[] types,Object...args)throws Exception{Method m=a.getClass().getDeclaredMethod(key,types);m.setAccessible(true);m.invoke(a,args);}
 @Before public void fixture()throws Exception{c=InstrumentationRegistry.getInstrumentation().getTargetContext();vault=new Vault(c);old=vault.read();prefs=new HashMap<>(c.getSharedPreferences("rookstride-ui",0).getAll());progress=c.getSharedPreferences("rookstride-deployment",0).getString("progress",null);c.getSharedPreferences("rookstride-deployment",0).edit().remove("progress").commit();a=node("North station","north.example.net","awg");b=node("South station","south.example.net","hysteria2");vault.write(new ArrayList<>(Arrays.asList(a,b)));c.getSharedPreferences("rookstride-ui",0).edit().putBoolean("onboarded",true).putString("selected",a.get("id")).putString("lastConnectedId",b.get("id")).commit();}
 Gateway node(String name,String host,String protocol)throws Exception{Gateway n=new Gateway();n.set("name",name);n.set("serverName",name);n.set("host",host);n.set("protocol",protocol);n.data.put("favorite",true);n.data.put("checkedAt",System.currentTimeMillis());n.data.put("snapshot",new JSONObject().put("services",new JSONObject().put("protocol",true)).put("edit_users",true).put("users",new JSONArray().put(new JSONObject().put("login","laptop").put("person","Laptop").put("device","Travel laptop"))));return n;}
 @After public void restore()throws Exception{vault.write(old);c.getSharedPreferences("rookstride-deployment",0).edit().putString("progress",progress).commit();SharedPreferences.Editor e=c.getSharedPreferences("rookstride-ui",0).edit().clear();for(Map.Entry<String,?> x:prefs.entrySet()){Object v=x.getValue();if(v instanceof String)e.putString(x.getKey(),(String)v);else if(v instanceof Boolean)e.putBoolean(x.getKey(),(Boolean)v);else if(v instanceof Long)e.putLong(x.getKey(),(Long)v);else if(v instanceof Integer)e.putInt(x.getKey(),(Integer)v);}e.commit();}
 static TextView label(View view,String text){if(view instanceof TextView&&text.contentEquals(((TextView)view).getText()))return (TextView)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){TextView found=label(((ViewGroup)view).getChildAt(i),text);if(found!=null)return found;}return null;}
 @Test public void protocolBrandsAndDisconnectedStatusStayReadable()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){onView(withContentDescription("Hide connections for North station")).perform(scrollTo(),click());onView(withContentDescription("Show connections for North station")).perform(click());onView(withContentDescription("Connect AmneziaWG 3.1 on North station")).perform(scrollTo());screen.onActivity(x->{View rows=x.findViewById(android.R.id.content).findViewWithTag("server-connections-"+a.get("id"));TextView name=label(rows,"AmneziaWG 3.1"),state=label(rows,"Disconnected");assertNotNull(name);assertNotNull(state);assertTrue("Brand word split across lines",name.getLayout().getLineEnd(0)>=10);assertTrue("Disconnected split across lines",state.getLayout().getLineEnd(0)>=12);});ScreenshotProof.save(c,"readable-home-protocol-rows");onView(withContentDescription("Manage North station")).perform(scrollTo(),click());onView(withContentDescription("Connect AmneziaWG 3.1")).perform(scrollTo());screen.onActivity(x->{TextView name=label(x.findViewById(android.R.id.content),"AmneziaWG 3.1");assertNotNull(name);assertTrue("Server protocol brand split across lines",name.getLayout().getLineEnd(0)>=10);});ScreenshotProof.save(c,"readable-server-protocol-cards");}}
 @Test public void favoritesSwipeAndOpenTheirOwnProtocolWithoutAnExtraOpenButton()throws Exception{try(ActivityScenario<RookstrideActivity> s=ActivityScenario.launch(RookstrideActivity.class)){onView(withText("Open connection")).check(doesNotExist());onView(withTagValue(is((Object)"quick-connection"))).perform(swipeLeft());for(int attempt=0;attempt<100;attempt++){final boolean[] idle={false};s.onActivity(x->{androidx.viewpager2.widget.ViewPager2 pager=x.findViewById(android.R.id.content).findViewWithTag("quick-connection");idle[0]=pager.getScrollState()==androidx.viewpager2.widget.ViewPager2.SCROLL_STATE_IDLE;});if(idle[0])break;if(attempt==99)fail("Quick connections did not settle after swipe");Thread.sleep(20);}onView(withContentDescription("Open AmneziaWG 3.1 settings")).perform(click());onView(withContentDescription("Remove from favorites")).check(matches(isDisplayed())).perform(click());onView(withContentDescription("Add to favorites")).check(matches(isDisplayed()));assertFalse(vault.read().get(0).data.optBoolean("favorite"));ScreenshotProof.save(c,"compact-favorite-protocol");}}
 @Test public void protocolSharingBelongsToEachUserAndEditingKeepsPhoneUse()throws Exception{try(ActivityScenario<RookstrideActivity> s=ActivityScenario.launch(RookstrideActivity.class)){s.onActivity(x->{try{call(x,"openVpn",new Class<?>[]{Gateway.class},a);}catch(Exception e){throw new AssertionError(e);}});onView(withText("Share")).check(doesNotExist());onView(withText("VPN users")).perform(scrollTo(),click());onView(withText("Share access")).perform(scrollTo()).check(matches(isCompletelyDisplayed()));onView(withText("Connection")).check(doesNotExist());onView(withText("Edit")).perform(scrollTo(),click());onView(withText("Use on this phone")).perform(scrollTo()).check(matches(isDisplayed()));onView(withText("Cancel")).perform(click());ScreenshotProof.save(c,"compact-user-actions");}}
 @Test public void breadcrumbsReachServerOrHomeAndScrollWithTheContent()throws Exception{try(ActivityScenario<RookstrideActivity> s=ActivityScenario.launch(RookstrideActivity.class)){s.onActivity(x->{try{call(x,"openVpn",new Class<?>[]{Gateway.class},a);call(x,"openUsers",new Class<?>[]{Gateway.class},a);}catch(Exception e){throw new AssertionError(e);}});onView(withContentDescription("Back to North station")).perform(click());onView(withText("Maintenance")).check(matches(isDisplayed()));onView(withContentDescription("Back to VPNs")).perform(click());onView(withContentDescription("Hide connections for North station")).perform(scrollTo(),click());onView(withContentDescription("Show connections for North station")).perform(click());onView(withContentDescription("Settings for AmneziaWG 3.1")).perform(scrollTo(),click());onView(withText("Uninstall this protocol")).perform(scrollTo());s.onActivity(x->{try{View crumbs=x.findViewById(android.R.id.content).findViewWithTag("context-navigation");int[] xy=new int[2],top=new int[2];crumbs.getLocationOnScreen(xy);((ScrollView)value(x,"pageScroll")).getLocationOnScreen(top);assertTrue("Breadcrumbs stayed pinned",xy[1]<top[1]);}catch(Exception e){throw new AssertionError(e);}});ScreenshotProof.save(c,"compact-scrolling-breadcrumbs");}}
 @Test public void nativeFaqExpandsOneAnswerWithoutDuplicateTopLevelLinks()throws Exception{try(ActivityScenario<RookstrideActivity> s=ActivityScenario.launch(RookstrideActivity.class)){onView(withContentDescription("App settings")).perform(click());onView(withText("Which apps use the VPN")).check(doesNotExist());onView(withText("Recent activity")).check(doesNotExist());onView(withText("Help & FAQ")).perform(scrollTo(),click());onView(withText("How do I connect?  +")).perform(click());onView(withSubstring("Open VPNs and tap Connect")).check(matches(isDisplayed()));onView(withText("How do I connect?  −")).perform(click());onView(withSubstring("Open VPNs and tap Connect")).check(matches(withEffectiveVisibility(Visibility.GONE)));onView(withText("Where do I add or share a VPN user?  +")).perform(scrollTo(),click());ScreenshotProof.save(c,"compact-native-faq");}}
 @Test public void serverCogIsAlignedAndProtocolCogIsIndependentOfConnect()throws Exception{try(ActivityScenario<RookstrideActivity> s=ActivityScenario.launch(RookstrideActivity.class)){onView(withContentDescription("Hide connections for North station")).perform(scrollTo(),click());onView(withContentDescription("Show connections for North station")).perform(click());onView(withContentDescription("Settings for AmneziaWG 3.1")).perform(scrollTo()).check(matches(isCompletelyDisplayed()));onView(withText("Users & sharing")).check(doesNotExist());onView(withContentDescription("Manage North station")).perform(scrollTo()).check(matches(isDisplayed()));onView(withContentDescription("Manage North station")).perform(scrollTo(),click());onView(withText("Refresh")).check(matches(isDisplayed()));onView(withText("Maintenance")).check(matches(isDisplayed()));ScreenshotProof.save(c,"compact-server-tools");}}
}
